270→// searchNotesHandler implements the search_notes tool
271→func searchNotesHandler(ctx context.Context, req *mcp.CallToolRequest, input SearchNotesInput) (*mcp.CallToolResult, SearchNotesOutput, error) {
272→	var results []string
273→	query := input.Query
274→
275→	// Try to compile as regex, if it fails, use literal string matching
276→	var re *regexp.Regexp
277→	var useRegex bool
278→	if compiled, err := regexp.Compile("(?i)" + query); err == nil {
279→		re = compiled
280→		useRegex = true
281→	}
282→
283→	// Walk through the vault directory
284→	err := filepath.Walk(vaultPath, func(path string, info os.FileInfo, err error) error {
285→		if err != nil {
286→			return nil // Skip files with errors
287→		}
288→
289→		// Skip directories
290→		if info.IsDir() {
291→			// Check if directory is allowed (not hidden)
292→			allowed, checkErr := isPathAllowed(path)
293→			if checkErr != nil || !allowed {
294→				return filepath.SkipDir
295→			}
296→			return nil
297→		}
298→
299→		// Only process markdown files
300→		if !strings.HasSuffix(strings.ToLower(path), ".md") {
301→			return nil
302→		}
303→
304→		// Check if file is allowed
305→		allowed, checkErr := isPathAllowed(path)
306→		if checkErr != nil || !allowed {
307→			return nil
308→		}
309→
310→		// Get filename
311→		filename := filepath.Base(path)
312→
313→		// Match against query
314→		matched := false
315→		if useRegex {
316→			matched = re.MatchString(filename)
317→		} else {
318→			matched = strings.Contains(strings.ToLower(filename), strings.ToLower(query))
319→		}
320→
321→		if matched {
322→			results = append(results, path)
323→			// Limit results
324→			if len(results) >= maxSearchResults {
325→				return filepath.SkipAll
326→			}
327→		}
328→
329→		return nil
330→	})
331→
332→	if err != nil {
333→		return nil, SearchNotesOutput{}, fmt.Errorf("failed to search notes: %w", err)
334→	}
335→
336→	output := SearchNotesOutput{
337→		Results: results,
338→	}
339→
340→	// Create text content for the result
341→	textContent := fmt.Sprintf("Found %d matching notes", len(results))
342→	if len(results) > 0 {
343→		textContent += ":\n" + strings.Join(results, "\n")
344→	}
345→
346→	result := &mcp.CallToolResult{
347→		Content: []mcp.Content{
348→			&mcp.TextContent{
349→				Text: textContent,
350→			},
351→		},
352→	}
353→
354→	return result, output, nil
355→}
