137→// slugify converts a title string into a URL/filename-safe slug
138→func slugify(s string) string {
139→	var b strings.Builder
140→	prevHyphen := false
141→	for _, r := range strings.ToLower(s) {
142→		if unicode.IsLetter(r) || unicode.IsDigit(r) {
143→			b.WriteRune(r)
144→			prevHyphen = false
145→		} else if !prevHyphen && b.Len() > 0 {
146→			b.WriteByte('-')
147→			prevHyphen = true
148→		}
149→	}
150→	result := b.String()
151→	return strings.TrimRight(result, "-")
152→}
