176→// resolveWithAncestors resolves symlinks by walking up to the nearest existing
177→// ancestor directory and re-appending the remaining path segments.
178→func resolveWithAncestors(absPath string) string {
179→	current := absPath
180→	var tail []string
181→	for {
182→		resolved, err := filepath.EvalSymlinks(current)
183→		if err == nil {
184→			// Found an existing ancestor — rejoin the tail
185→			for i := len(tail) - 1; i >= 0; i-- {
186→				resolved = filepath.Join(resolved, tail[i])
187→			}
188→			return resolved
189→		}
190→		parent := filepath.Dir(current)
191→		if parent == current {
192→			// Reached filesystem root without finding existing path
193→			return absPath
194→		}
195→		tail = append(tail, filepath.Base(current))
196→		current = parent
197→	}
198→}
