200→// isPathAllowed checks if a given path is within the allowed vault directory
201→// and doesn't access hidden files or directories
202→func isPathAllowed(path string) (bool, error) {
203→	// Expand home directory
204→	if strings.HasPrefix(path, "~") {
205→		home, err := os.UserHomeDir()
206→		if err != nil {
207→			return false, fmt.Errorf("failed to get home directory: %w", err)
208→		}
209→		path = filepath.Join(home, path[1:])
210→	}
211→
212→	// Get absolute path
213→	absPath, err := filepath.Abs(path)
214→	if err != nil {
215→		return false, fmt.Errorf("failed to get absolute path: %w", err)
216→	}
217→
218→	// Resolve symlinks
219→	resolvedPath, err := filepath.EvalSymlinks(absPath)
220→	if err != nil {
221→		// If the path doesn't exist, walk up to the nearest existing
222→		// ancestor, resolve its symlinks, then re-append the remainder.
223→		if os.IsNotExist(err) {
224→			resolvedPath = resolveWithAncestors(absPath)
225→		} else {
226→			return false, fmt.Errorf("failed to resolve symlinks: %w", err)
227→		}
228→	}
229→
230→	// Get absolute vault path
231→	absVaultPath, err := filepath.Abs(vaultPath)
232→	if err != nil {
233→		return false, fmt.Errorf("failed to get absolute vault path: %w", err)
234→	}
235→
236→	// Resolve vault symlinks
237→	resolvedVaultPath, err := filepath.EvalSymlinks(absVaultPath)
238→	if err != nil {
239→		if !os.IsNotExist(err) {
240→			return false, fmt.Errorf("failed to resolve vault symlinks: %w", err)
241→		}
242→		resolvedVaultPath = resolveWithAncestors(absVaultPath)
243→	}
244→
245→	// Clean paths
246→	cleanPath := filepath.Clean(resolvedPath)
247→	cleanVaultPath := filepath.Clean(resolvedVaultPath)
248→
249→	// Check if path is within vault
250→	if !strings.HasPrefix(cleanPath, cleanVaultPath) {
251→		return false, nil
252→	}
253→
254→	// Check for hidden files/directories
255→	relPath, err := filepath.Rel(cleanVaultPath, cleanPath)
256→	if err != nil {
257→		return false, fmt.Errorf("failed to get relative path: %w", err)
258→	}
259→
260→	pathParts := strings.Split(relPath, string(filepath.Separator))
261→	for _, part := range pathParts {
262→		if strings.HasPrefix(part, ".") && part != "." && part != ".." {
263→			return false, nil
264→		}
265→	}
266→
267→	return true, nil
268→}
