357→// readNotesHandler implements the read_notes tool
358→func readNotesHandler(ctx context.Context, req *mcp.CallToolRequest, input ReadNotesInput) (*mcp.CallToolResult, ReadNotesOutput, error) {
359→	notes := make([]NoteContent, 0, len(input.Paths))
360→
361→	for _, path := range input.Paths {
362→		note := NoteContent{
363→			Path: path,
364→		}
365→
366→		// Check if path is allowed
367→		allowed, err := isPathAllowed(path)
368→		if err != nil {
369→			note.Error = fmt.Sprintf("Path validation error: %v", err)
370→			notes = append(notes, note)
371→			continue
372→		}
373→
374→		if !allowed {
375→			note.Error = "Access denied: path is outside vault or is a hidden file"
376→			notes = append(notes, note)
377→			continue
378→		}
379→
380→		// Read file content
381→		content, err := os.ReadFile(path)
382→		if err != nil {
383→			note.Error = fmt.Sprintf("Failed to read file: %v", err)
384→			notes = append(notes, note)
385→			continue
386→		}
387→
388→		note.Content = string(content)
389→		notes = append(notes, note)
390→	}
391→
392→	output := ReadNotesOutput{
393→		Notes: notes,
394→	}
395→
396→	// Create text content for the result
397→	var textParts []string
398→	for _, note := range notes {
399→		if note.Error != "" {
400→			textParts = append(textParts, fmt.Sprintf("## %s\nError: %s", note.Path, note.Error))
401→		} else {
402→			textParts = append(textParts, fmt.Sprintf("## %s\n%s", note.Path, note.Content))
403→		}
404→	}
405→
406→	result := &mcp.CallToolResult{
407→		Content: []mcp.Content{
408→			&mcp.TextContent{
409→				Text: strings.Join(textParts, "\n\n"),
410→			},
411→		},
412→	}
413→
414→	return result, output, nil
415→}
