884→func main() {
885→	// Check command line arguments
886→	if len(os.Args) < 2 {
887→		log.Fatal("Usage: mcp-obsidian <vault-path>")
888→	}
889→
890→	// Get vault path from command line
891→	vaultPath = os.Args[1]
892→
893→	// Expand home directory
894→	if strings.HasPrefix(vaultPath, "~") {
895→		home, err := os.UserHomeDir()
896→		if err != nil {
897→			log.Fatalf("Failed to get home directory: %v", err)
898→		}
899→		vaultPath = filepath.Join(home, vaultPath[1:])
900→	}
901→
902→	// Check if vault path exists
903→	if _, err := os.Stat(vaultPath); os.IsNotExist(err) {
904→		log.Fatalf("Vault path does not exist: %s", vaultPath)
905→	}
906→
907→	// Create MCP server
908→	server := mcp.NewServer(&mcp.Implementation{
909→		Name:    "mcp-obsidian",
910→		Version: "3.0.0",
911→	}, nil)
912→
913→	// Register search_notes tool
914→	mcp.AddTool(server, &mcp.Tool{
915→		Name:        "search_notes",
916→		Description: "Search for notes by filename using case-insensitive matching. Supports regex patterns.",
917→	}, searchNotesHandler)
918→
919→	// Register read_notes tool
920→	mcp.AddTool(server, &mcp.Tool{
921→		Name:        "read_notes",
922→		Description: "Read the content of one or more notes. Returns content with error handling per file.",
923→	}, readNotesHandler)
924→
925→	// Register create_note tool
926→	mcp.AddTool(server, &mcp.Tool{
927→		Name:        "create_note",
928→		Description: "Create a new note with YYYY-MM-DD_slug.md naming convention and YAML frontmatter. Supports tags and subfolder placement.",
929→	}, createNoteHandler)
930→
931→	// Register update_note tool
932→	mcp.AddTool(server, &mcp.Tool{
933→		Name:        "update_note",
934→		Description: "Update an existing note's content. Supports 'replace' (overwrite) and 'append' modes.",
935→	}, updateNoteHandler)
936→
937→	// Register delete_note tool
938→	mcp.AddTool(server, &mcp.Tool{
939→		Name:        "delete_note",
940→		Description: "Delete a markdown note from the vault. Only .md files can be deleted.",
941→	}, deleteNoteHandler)
942→
943→	// Register search_content tool
944→	mcp.AddTool(server, &mcp.Tool{
945→		Name:        "search_content",
946→		Description: "Full-text search across note bodies. Returns matching file paths, line numbers, and snippets. Supports regex patterns.",
947→	}, searchContentHandler)
948→
949→	// Register get_backlinks tool
950→	mcp.AddTool(server, &mcp.Tool{
951→		Name:        "get_backlinks",
952→		Description: "Find all notes that link to a given note via [[wikilinks]]. Supports [[note]] and [[note|alias]] syntax.",
953→	}, getBacklinksHandler)
954→
955→	// Register list_tags tool
956→	mcp.AddTool(server, &mcp.Tool{
957→		Name:        "list_tags",
958→		Description: "List all tags found across the vault from YAML frontmatter and inline #tags. Optionally filter by prefix.",
959→	}, listTagsHandler)
960→
961→	// Log server start to stderr (stdout is used for MCP communication)
962→	fmt.Fprintf(os.Stderr, "MCP Obsidian server starting...\n")
963→	fmt.Fprintf(os.Stderr, "Vault path: %s\n", vaultPath)
964→
965→	// Run the server with stdio transport
966→	if err := server.Run(context.Background(), &mcp.StdioTransport{}); err != nil {
967→		log.Fatalf("Server error: %v", err)
968→	}
969→}
