  67→// TestIsPathAllowed tests the path validation function
  68→func TestIsPathAllowed(t *testing.T) {
  69→	tmpVault := setupTestVault(t)
  70→	defer cleanupTestVault(t, tmpVault)
  71→
  72→	// Set global vaultPath for testing
  73→	originalVaultPath := vaultPath
  74→	vaultPath = tmpVault
  75→	defer func() { vaultPath = originalVaultPath }()
  76→
  77→	tests := []struct {
  78→		name    string
  79→		path    string
  80→		want    bool
  81→		wantErr bool
  82→	}{
  83→		{
  84→			name: "valid file in vault",
  85→			path: filepath.Join(tmpVault, "note1.md"),
  86→			want: true,
  87→		},
  88→		{
  89→			name: "valid file in subfolder",
  90→			path: filepath.Join(tmpVault, "subfolder", "nested-note.md"),
  91→			want: true,
  92→		},
  93→		{
  94→			name: "hidden file should be rejected",
  95→			path: filepath.Join(tmpVault, ".hidden", "secret.md"),
  96→			want: false,
  97→		},
  98→		{
  99→			name: "hidden file in subfolder should be rejected",
 100→			path: filepath.Join(tmpVault, "subfolder", ".hidden-note.md"),
 101→			want: false,
 102→		},
 103→		{
 104→			name: "file outside vault should be rejected",
 105→			path: "/tmp/outside-vault.md",
 106→			want: false,
 107→		},
 108→		{
 109→			name: "path traversal attempt should be rejected",
 110→			path: filepath.Join(tmpVault, "..", "escape.md"),
 111→			want: false,
 112→		},
 113→		{
 114→			name: "non-existent file in vault should be allowed",
 115→			path: filepath.Join(tmpVault, "nonexistent-file.md"),
 116→			want: true,
 117→		},
 118→		{
 119→			name: "non-existent file outside vault should be rejected",
 120→			path: "/tmp/nonexistent-outside.md",
 121→			want: false,
 122→		},
 123→		{
 124→			name: "path with dot segments within vault",
 125→			path: filepath.Join(tmpVault, "subfolder", "..", "note1.md"),
 126→			want: true,
 127→		},
 128→		{
 129→			name: "relative path within vault",
 130→			path: filepath.Join(tmpVault, ".", "note1.md"),
 131→			want: true,
 132→		},
 133→	}
 134→
 135→	for _, tt := range tests {
 136→		t.Run(tt.name, func(t *testing.T) {
 137→			got, testErr := isPathAllowed(tt.path)
 138→			if (testErr != nil) != tt.wantErr {
 139→				t.Errorf("isPathAllowed() error = %v, wantErr %v", testErr, tt.wantErr)
 140→				return
 141→			}
 142→			if got != tt.want {
 143→				t.Errorf("isPathAllowed() = %v, want %v", got, tt.want)
 144→			}
 145→		})
 146→	}
 147→}
