 535→				}
 536→			}
 537→
 538→			// Check that result content is properly formatted
 539→			if result == nil {
 540→				t.Error("searchNotesHandler() result is nil")
 541→				return
 542→			}
 543→
 544→			if len(result.Content) == 0 {
