417→// createNoteHandler implements the create_note tool
418→func createNoteHandler(ctx context.Context, req *mcp.CallToolRequest, input CreateNoteInput) (*mcp.CallToolResult, CreateNoteOutput, error) {
419→	if input.Title == "" {
420→		return nil, CreateNoteOutput{}, fmt.Errorf("title is required")
421→	}
422→
423→	slug := slugify(input.Title)
424→	if slug == "" {
425→		return nil, CreateNoteOutput{}, fmt.Errorf("title produces an empty slug")
426→	}
427→
428→	today := time.Now().Format("2006-01-02")
429→	filename := today + "_" + slug + ".md"
430→
431→	dir := vaultPath
432→	if input.Folder != "" {
433→		dir = filepath.Join(vaultPath, input.Folder)
434→	}
435→
436→	fullPath := filepath.Join(dir, filename)
437→
438→	allowed, err := isPathAllowed(fullPath)
439→	if err != nil {
440→		return nil, CreateNoteOutput{}, fmt.Errorf("path validation error: %w", err)
441→	}
442→	if !allowed {
443→		return nil, CreateNoteOutput{}, fmt.Errorf("access denied: path is outside vault or is a hidden file")
444→	}
445→
446→	if _, err := os.Stat(fullPath); err == nil {
447→		return nil, CreateNoteOutput{}, fmt.Errorf("file already exists: %s", fullPath)
448→	}
449→
450→	if err := os.MkdirAll(dir, 0755); err != nil {
451→		return nil, CreateNoteOutput{}, fmt.Errorf("failed to create directory: %w", err)
452→	}
453→
454→	frontmatter := generateFrontmatter(input.Tags, today, today)
455→
456→	var content strings.Builder
457→	content.WriteString(frontmatter)
458→	content.WriteString("\n# ")
459→	content.WriteString(input.Title)
460→	content.WriteByte('\n')
461→	if input.Content != "" {
462→		content.WriteByte('\n')
463→		content.WriteString(input.Content)
464→		content.WriteByte('\n')
465→	}
466→
467→	if err := os.WriteFile(fullPath, []byte(content.String()), 0644); err != nil {
468→		return nil, CreateNoteOutput{}, fmt.Errorf("failed to write file: %w", err)
469→	}
470→
471→	output := CreateNoteOutput{Path: fullPath}
472→	result := &mcp.CallToolResult{
473→		Content: []mcp.Content{
474→			&mcp.TextContent{Text: fmt.Sprintf("Created note: %s", fullPath)},
475→		},
476→	}
477→	return result, output, nil
478→}
