480→// updateNoteHandler implements the update_note tool
481→func updateNoteHandler(ctx context.Context, req *mcp.CallToolRequest, input UpdateNoteInput) (*mcp.CallToolResult, UpdateNoteOutput, error) {
482→	allowed, err := isPathAllowed(input.Path)
483→	if err != nil {
484→		return nil, UpdateNoteOutput{}, fmt.Errorf("path validation error: %w", err)
485→	}
486→	if !allowed {
487→		return nil, UpdateNoteOutput{}, fmt.Errorf("access denied: path is outside vault or is a hidden file")
488→	}
489→
490→	if _, err := os.Stat(input.Path); os.IsNotExist(err) {
491→		return nil, UpdateNoteOutput{}, fmt.Errorf("file does not exist: %s", input.Path)
492→	}
493→
494→	mode := input.Mode
495→	if mode == "" {
496→		mode = "replace"
497→	}
498→
499→	switch mode {
500→	case "replace":
501→		if err := os.WriteFile(input.Path, []byte(input.Content), 0644); err != nil {
502→			return nil, UpdateNoteOutput{}, fmt.Errorf("failed to write file: %w", err)
503→		}
504→	case "append":
505→		existing, err := os.ReadFile(input.Path)
506→		if err != nil {
507→			return nil, UpdateNoteOutput{}, fmt.Errorf("failed to read file: %w", err)
508→		}
509→		newContent := string(existing) + "\n\n" + input.Content
510→		if err := os.WriteFile(input.Path, []byte(newContent), 0644); err != nil {
511→			return nil, UpdateNoteOutput{}, fmt.Errorf("failed to write file: %w", err)
512→		}
513→	default:
514→		return nil, UpdateNoteOutput{}, fmt.Errorf("invalid mode: %s (must be 'replace' or 'append')", mode)
515→	}
516→
517→	output := UpdateNoteOutput{Path: input.Path}
518→	result := &mcp.CallToolResult{
519→		Content: []mcp.Content{
520→			&mcp.TextContent{Text: fmt.Sprintf("Updated note (%s): %s", mode, input.Path)},
521→		},
522→	}
523→	return result, output, nil
524→}
525→
526→// deleteNoteHandler implements the delete_note tool
527→func deleteNoteHandler(ctx context.Context, req *mcp.CallToolRequest, input DeleteNoteInput) (*mcp.CallToolResult, DeleteNoteOutput, error) {
528→	if !strings.HasSuffix(strings.ToLower(input.Path), ".md") {
529→		return nil, DeleteNoteOutput{}, fmt.Errorf("can only delete .md files")
530→	}
531→
532→	allowed, err := isPathAllowed(input.Path)
533→	if err != nil {
534→		return nil, DeleteNoteOutput{}, fmt.Errorf("path validation error: %w", err)
535→	}
536→	if !allowed {
537→		return nil, DeleteNoteOutput{}, fmt.Errorf("access denied: path is outside vault or is a hidden file")
538→	}
539→
540→	info, err := os.Stat(input.Path)
541→	if os.IsNotExist(err) {
542→		return nil, DeleteNoteOutput{}, fmt.Errorf("file does not exist: %s", input.Path)
543→	}
544→	if err != nil {
545→		return nil, DeleteNoteOutput{}, fmt.Errorf("failed to stat file: %w", err)
546→	}
547→	if info.IsDir() {
548→		return nil, DeleteNoteOutput{}, fmt.Errorf("cannot delete directories")
549→	}
550→
551→	if err := os.Remove(input.Path); err != nil {
552→		return nil, DeleteNoteOutput{}, fmt.Errorf("failed to delete file: %w", err)
553→	}
554→
555→	output := DeleteNoteOutput(input)
556→	result := &mcp.CallToolResult{
557→		Content: []mcp.Content{
558→			&mcp.TextContent{Text: fmt.Sprintf("Deleted note: %s", input.Path)},
559→		},
560→	}
561→	return result, output, nil
562→}
