564→// searchContentHandler implements the search_content tool
565→func searchContentHandler(ctx context.Context, req *mcp.CallToolRequest, input SearchContentInput) (*mcp.CallToolResult, SearchContentOutput, error) {
566→	query := input.Query
567→
568→	var re *regexp.Regexp
569→	var useRegex bool
570→	if compiled, err := regexp.Compile("(?i)" + query); err == nil {
571→		re = compiled
572→		useRegex = true
573→	}
574→
575→	var results []ContentMatch
576→
577→	err := filepath.Walk(vaultPath, func(path string, info os.FileInfo, err error) error {
578→		if err != nil {
579→			return nil
580→		}
581→
582→		if info.IsDir() {
583→			allowed, checkErr := isPathAllowed(path)
584→			if checkErr != nil || !allowed {
585→				return filepath.SkipDir
586→			}
587→			return nil
588→		}
589→
590→		if !strings.HasSuffix(strings.ToLower(path), ".md") {
591→			return nil
592→		}
593→
594→		allowed, checkErr := isPathAllowed(path)
595→		if checkErr != nil || !allowed {
596→			return nil
597→		}
598→
599→		data, err := os.ReadFile(path)
600→		if err != nil {
601→			return nil
602→		}
603→
604→		lines := strings.Split(string(data), "\n")
605→		for lineNum, line := range lines {
606→
607→			matched := false
608→			if useRegex {
609→				matched = re.MatchString(line)
610→			} else {
611→				matched = strings.Contains(strings.ToLower(line), strings.ToLower(query))
612→			}
613→
614→			if matched {
615→				results = append(results, ContentMatch{
616→					Path:    path,
617→					Snippet: line,
618→					Line:    lineNum + 1,
619→				})
620→				if len(results) >= maxSearchResults {
621→					return filepath.SkipAll
622→				}
623→			}
624→		}
625→
626→		return nil
627→	})
628→
629→	if err != nil {
630→		return nil, SearchContentOutput{}, fmt.Errorf("failed to search content: %w", err)
631→	}
632→
633→	output := SearchContentOutput{Results: results}
634→
635→	textContent := fmt.Sprintf("Found %d matching lines", len(results))
636→	if len(results) > 0 {
637→		var lines []string
638→		for _, m := range results {
639→			lines = append(lines, fmt.Sprintf("%s:%d: %s", m.Path, m.Line, m.Snippet))
640→		}
641→		textContent += ":\n" + strings.Join(lines, "\n")
642→	}
643→
644→	result := &mcp.CallToolResult{
645→		Content: []mcp.Content{
646→			&mcp.TextContent{Text: textContent},
647→		},
648→	}
649→	return result, output, nil
650→}
651→
652→// getBacklinksHandler implements the get_backlinks tool
653→func getBacklinksHandler(ctx context.Context, req *mcp.CallToolRequest, input GetBacklinksInput) (*mcp.CallToolResult, GetBacklinksOutput, error) {
654→	if input.NoteName == "" {
655→		return nil, GetBacklinksOutput{}, fmt.Errorf("note_name is required")
656→	}
657→
658→	noteName := strings.TrimSuffix(input.NoteName, ".md")
659→	wikilinkRe := regexp.MustCompile(`\[\[([^\]|]+)(?:\|[^\]]+)?\]\]`)
660→
661→	var results []Backlink
662→
663→	err := filepath.Walk(vaultPath, func(path string, info os.FileInfo, err error) error {
664→		if err != nil {
665→			return nil
666→		}
667→
668→		if info.IsDir() {
669→			allowed, checkErr := isPathAllowed(path)
670→			if checkErr != nil || !allowed {
671→				return filepath.SkipDir
672→			}
673→			return nil
674→		}
675→
676→		if !strings.HasSuffix(strings.ToLower(path), ".md") {
677→			return nil
678→		}
679→
680→		allowed, checkErr := isPathAllowed(path)
681→		if checkErr != nil || !allowed {
682→			return nil
683→		}
684→
685→		// Exclude the target note itself
686→		baseName := strings.TrimSuffix(filepath.Base(path), ".md")
687→		if strings.EqualFold(baseName, noteName) {
688→			return nil
689→		}
690→
691→		data, err := os.ReadFile(path)
692→		if err != nil {
693→			return nil
694→		}
695→
696→		lines := strings.Split(string(data), "\n")
697→		for _, line := range lines {
698→			matches := wikilinkRe.FindAllStringSubmatch(line, -1)
699→			for _, match := range matches {
700→				if len(match) >= 2 {
701→					linkTarget := strings.TrimSuffix(match[1], ".md")
702→					if strings.EqualFold(linkTarget, noteName) {
703→						results = append(results, Backlink{
704→							Path: path,
705→							Line: line,
706→						})
707→						break // one match per line is enough
708→					}
709→				}
710→			}
711→		}
712→
713→		return nil
714→	})
715→
716→	if err != nil {
717→		return nil, GetBacklinksOutput{}, fmt.Errorf("failed to search backlinks: %w", err)
718→	}
719→
720→	output := GetBacklinksOutput{Results: results}
721→
722→	textContent := fmt.Sprintf("Found %d backlinks to [[%s]]", len(results), noteName)
723→	if len(results) > 0 {
724→		var lines []string
725→		for _, bl := range results {
726→			lines = append(lines, fmt.Sprintf("%s: %s", bl.Path, bl.Line))
727→		}
728→		textContent += ":\n" + strings.Join(lines, "\n")
729→	}
730→
731→	result := &mcp.CallToolResult{
732→		Content: []mcp.Content{
733→			&mcp.TextContent{Text: textContent},
734→		},
735→	}
736→	return result, output, nil
737→}
