					t.Fatalf("Expected 1 note, got %d", len(output.Notes))
				}
				n := output.Notes[0]
				if n.Error != "" {
					t.Errorf("Expected no error, got: %s", n.Error)
				}
				if !strings.Contains(n.Content, "# Note 1") {
					t.Errorf("Expected content to contain '# Note 1', got: %s", n.Content)
				}
			},
