				}
				n := output.Notes[0]
				if n.Error == "" {
					t.Error("Expected error for non-existent file, got none")
				}
				if !strings.Contains(n.Error, "Failed to read file") {
					t.Errorf("Expected 'Failed to read file' error, got: %s", n.Error)
