137→// slugify converts a title string into a URL/filename-safe slug
138→func slugify(s string) string {
139→	var b strings.Builder
140→	prevHyphen := false
141→	for _, r := range strings.ToLower(s) {
142→		if unicode.IsLetter(r) || unicode.IsDigit(r) {
143→			b.WriteRune(r)
144→			prevHyphen = false
145→		} else if !prevHyphen && b.Len() > 0 {
146→			b.WriteByte('-')
147→			prevHyphen = true
148→		}
149→	}
150→	result := b.String()
151→	return strings.TrimRight(result, "-")
152→}
153→
154→// generateFrontmatter creates YAML frontmatter with tags and timestamps
155→func generateFrontmatter(tags []string, created, updated string) string {
156→	var b strings.Builder
157→	b.WriteString("---\n")
158→	if len(tags) > 0 {
159→		b.WriteString("tags:\n")
160→		for _, tag := range tags {
161→			b.WriteString("  - ")
162→			b.WriteString(tag)
163→			b.WriteByte('\n')
164→		}
165→	}
166→	b.WriteString("created: ")
167→	b.WriteString(created)
168→	b.WriteByte('\n')
169→	b.WriteString("updated: ")
170→	b.WriteString(updated)
171→	b.WriteByte('\n')
172→	b.WriteString("---\n")
173→	return b.String()
174→}
