270→// searchNotesHandler implements the search_notes tool
271→func searchNotesHandler(ctx context.Context, req *mcp.CallToolRequest, input SearchNotesInput) (*mcp.CallToolResult, SearchNotesOutput, error) {
272→	var results []string
273→	query := input.Query
274→
275→	// Try to compile as regex, if it fails, use literal string matching
276→	var re *regexp.Regexp
277→	var useRegex bool
278→	if compiled, err := regexp.Compile("(?i)" + query); err == nil {
279→		re = compiled
280→		useRegex = true
281→	}
282→
283→	// Walk through the vault directory
284→	err := filepath.Walk(vaultPath, func(path string, info os.FileInfo, err error) error {
285→		if err != nil {
286→			return nil // Skip files with errors
287→		}
288→
289→		// Skip directories
290→		if info.IsDir() {
291→			// Check if directory is allowed (not hidden)
292→			allowed, checkErr := isPathAllowed(path)
293→			if checkErr != nil || !allowed {
294→				return filepath.SkipDir
295→			}
296→			return nil
297→		}
298→
299→		// Only process markdown files
300→		if !strings.HasSuffix(strings.ToLower(path), ".md") {
301→			return nil
302→		}
303→
304→		// Check if file is allowed
305→		allowed, checkErr := isPathAllowed(path)
306→		if checkErr != nil || !allowed {
307→			return nil
308→		}
309→
310→		// Get filename
311→		filename := filepath.Base(path)
312→
313→		// Match against query
314→		matched := false
315→		if useRegex {
316→			matched = re.MatchString(filename)
317→		} else {
318→			matched = strings.Contains(strings.ToLower(filename), strings.ToLower(query))
319→		}
320→
321→		if matched {
322→			results = append(results, path)
323→			// Limit results
324→			if len(results) >= maxSearchResults {
325→				return filepath.SkipAll
326→			}
327→		}
328→
329→		return nil
330→	})
331→
332→	if err != nil {
333→		return nil, SearchNotesOutput{}, fmt.Errorf("failed to search notes: %w", err)
334→	}
335→
336→	output := SearchNotesOutput{
337→		Results: results,
338→	}
339→
340→	// Create text content for the result
341→	textContent := fmt.Sprintf("Found %d matching notes", len(results))
342→	if len(results) > 0 {
343→		textContent += ":\n" + strings.Join(results, "\n")
344→	}
345→
346→	result := &mcp.CallToolResult{
347→		Content: []mcp.Content{
348→			&mcp.TextContent{
349→				Text: textContent,
350→			},
351→		},
352→	}
353→
354→	return result, output, nil
355→}
356→
357→// readNotesHandler implements the read_notes tool
358→func readNotesHandler(ctx context.Context, req *mcp.CallToolRequest, input ReadNotesInput) (*mcp.CallToolResult, ReadNotesOutput, error) {
359→	notes := make([]NoteContent, 0, len(input.Paths))
360→
361→	for _, path := range input.Paths {
362→		note := NoteContent{
363→			Path: path,
364→		}
365→
366→		// Check if path is allowed
367→		allowed, err := isPathAllowed(path)
368→		if err != nil {
369→			note.Error = fmt.Sprintf("Path validation error: %v", err)
370→			notes = append(notes, note)
371→			continue
372→		}
373→
374→		if !allowed {
375→			note.Error = "Access denied: path is outside vault or is a hidden file"
376→			notes = append(notes, note)
377→			continue
378→		}
379→
380→		// Read file content
381→		content, err := os.ReadFile(path)
382→		if err != nil {
383→			note.Error = fmt.Sprintf("Failed to read file: %v", err)
384→			notes = append(notes, note)
385→			continue
386→		}
387→
388→		note.Content = string(content)
389→		notes = append(notes, note)
390→	}
391→
392→	output := ReadNotesOutput{
393→		Notes: notes,
394→	}
395→
396→	// Create text content for the result
397→	var textParts []string
398→	for _, note := range notes {
399→		if note.Error != "" {
400→			textParts = append(textParts, fmt.Sprintf("## %s\nError: %s", note.Path, note.Error))
401→		} else {
402→			textParts = append(textParts, fmt.Sprintf("## %s\n%s", note.Path, note.Content))
403→		}
404→	}
405→
406→	result := &mcp.CallToolResult{
407→		Content: []mcp.Content{
408→			&mcp.TextContent{
409→				Text: strings.Join(textParts, "\n\n"),
410→			},
411→		},
412→	}
413→
414→	return result, output, nil
415→}
416→
417→// createNoteHandler implements the create_note tool
418→func createNoteHandler(ctx context.Context, req *mcp.CallToolRequest, input CreateNoteInput) (*mcp.CallToolResult, CreateNoteOutput, error) {
419→	if input.Title == "" {
420→		return nil, CreateNoteOutput{}, fmt.Errorf("title is required")
421→	}
422→
423→	slug := slugify(input.Title)
424→	if slug == "" {
425→		return nil, CreateNoteOutput{}, fmt.Errorf("title produces an empty slug")
426→	}
427→
428→	today := time.Now().Format("2006-01-02")
429→	filename := today + "_" + slug + ".md"
430→
431→	dir := vaultPath
432→	if input.Folder != "" {
433→		dir = filepath.Join(vaultPath, input.Folder)
434→	}
435→
436→	fullPath := filepath.Join(dir, filename)
437→
438→	allowed, err := isPathAllowed(fullPath)
439→	if err != nil {
440→		return nil, CreateNoteOutput{}, fmt.Errorf("path validation error: %w", err)
441→	}
442→	if !allowed {
443→		return nil, CreateNoteOutput{}, fmt.Errorf("access denied: path is outside vault or is a hidden file")
444→	}
445→
446→	if _, err := os.Stat(fullPath); err == nil {
447→		return nil, CreateNoteOutput{}, fmt.Errorf("file already exists: %s", fullPath)
448→	}
449→
450→	if err := os.MkdirAll(dir, 0755); err != nil {
451→		return nil, CreateNoteOutput{}, fmt.Errorf("failed to create directory: %w", err)
452→	}
453→
454→	frontmatter := generateFrontmatter(input.Tags, today, today)
455→
456→	var content strings.Builder
457→	content.WriteString(frontmatter)
458→	content.WriteString("\n# ")
459→	content.WriteString(input.Title)
460→	content.WriteByte('\n')
461→	if input.Content != "" {
462→		content.WriteByte('\n')
463→		content.WriteString(input.Content)
464→		content.WriteByte('\n')
465→	}
466→
467→	if err := os.WriteFile(fullPath, []byte(content.String()), 0644); err != nil {
468→		return nil, CreateNoteOutput{}, fmt.Errorf("failed to write file: %w", err)
469→	}
470→
471→	output := CreateNoteOutput{Path: fullPath}
472→	result := &mcp.CallToolResult{
473→		Content: []mcp.Content{
474→			&mcp.TextContent{Text: fmt.Sprintf("Created note: %s", fullPath)},
475→		},
476→	}
477→	return result, output, nil
478→}
479→
480→// updateNoteHandler implements the update_note tool
481→func updateNoteHandler(ctx context.Context, req *mcp.CallToolRequest, input UpdateNoteInput) (*mcp.CallToolResult, UpdateNoteOutput, error) {
482→	allowed, err := isPathAllowed(input.Path)
483→	if err != nil {
484→		return nil, UpdateNoteOutput{}, fmt.Errorf("path validation error: %w", err)
485→	}
486→	if !allowed {
487→		return nil, UpdateNoteOutput{}, fmt.Errorf("access denied: path is outside vault or is a hidden file")
488→	}
489→
490→	if _, err := os.Stat(input.Path); os.IsNotExist(err) {
491→		return nil, UpdateNoteOutput{}, fmt.Errorf("file does not exist: %s", input.Path)
492→	}
493→
494→	mode := input.Mode
495→	if mode == "" {
496→		mode = "replace"
497→	}
498→
499→	switch mode {
500→	case "replace":
501→		if err := os.WriteFile(input.Path, []byte(input.Content), 0644); err != nil {
502→			return nil, UpdateNoteOutput{}, fmt.Errorf("failed to write file: %w", err)
503→		}
504→	case "append":
505→		existing, err := os.ReadFile(input.Path)
506→		if err != nil {
507→			return nil, UpdateNoteOutput{}, fmt.Errorf("failed to read file: %w", err)
508→		}
509→		newContent := string(existing) + "\n\n" + input.Content
510→		if err := os.WriteFile(input.Path, []byte(newContent), 0644); err != nil {
511→			return nil, UpdateNoteOutput{}, fmt.Errorf("failed to write file: %w", err)
512→		}
513→	default:
514→		return nil, UpdateNoteOutput{}, fmt.Errorf("invalid mode: %s (must be 'replace' or 'append')", mode)
515→	}
516→
517→	output := UpdateNoteOutput{Path: input.Path}
518→	result := &mcp.CallToolResult{
519→		Content: []mcp.Content{
520→			&mcp.TextContent{Text: fmt.Sprintf("Updated note (%s): %s", mode, input.Path)},
521→		},
522→	}
523→	return result, output, nil
524→}
525→
526→// deleteNoteHandler implements the delete_note tool
527→func deleteNoteHandler(ctx context.Context, req *mcp.CallToolRequest, input DeleteNoteInput) (*mcp.CallToolResult, DeleteNoteOutput, error) {
528→	if !strings.HasSuffix(strings.ToLower(input.Path), ".md") {
529→		return nil, DeleteNoteOutput{}, fmt.Errorf("can only delete .md files")
530→	}
531→
532→	allowed, err := isPathAllowed(input.Path)
533→	if err != nil {
534→		return nil, DeleteNoteOutput{}, fmt.Errorf("path validation error: %w", err)
535→	}
536→	if !allowed {
537→		return nil, DeleteNoteOutput{}, fmt.Errorf("access denied: path is outside vault or is a hidden file")
538→	}
539→
540→	info, err := os.Stat(input.Path)
541→	if os.IsNotExist(err) {
542→		return nil, DeleteNoteOutput{}, fmt.Errorf("file does not exist: %s", input.Path)
543→	}
544→	if err != nil {
545→		return nil, DeleteNoteOutput{}, fmt.Errorf("failed to stat file: %w", err)
546→	}
547→	if info.IsDir() {
548→		return nil, DeleteNoteOutput{}, fmt.Errorf("cannot delete directories")
549→	}
550→
551→	if err := os.Remove(input.Path); err != nil {
552→		return nil, DeleteNoteOutput{}, fmt.Errorf("failed to delete file: %w", err)
553→	}
554→
555→	output := DeleteNoteOutput(input)
556→	result := &mcp.CallToolResult{
557→		Content: []mcp.Content{
558→			&mcp.TextContent{Text: fmt.Sprintf("Deleted note: %s", input.Path)},
559→		},
560→	}
561→	return result, output, nil
562→}
