739→// listTagsHandler implements the list_tags tool
740→func listTagsHandler(ctx context.Context, req *mcp.CallToolRequest, input ListTagsInput) (*mcp.CallToolResult, ListTagsOutput, error) {
741→	tagCounts := make(map[string]int)
742→
743→	// Regex for inline #tags (not inside code blocks)
744→	inlineTagRe := regexp.MustCompile(`(?:^|\s)#([a-zA-Z][a-zA-Z0-9_/-]*)`)
745→
746→	err := filepath.Walk(vaultPath, func(path string, info os.FileInfo, err error) error {
747→		if err != nil {
748→			return nil
749→		}
750→
751→		if info.IsDir() {
752→			allowed, checkErr := isPathAllowed(path)
753→			if checkErr != nil || !allowed {
754→				return filepath.SkipDir
755→			}
756→			return nil
757→		}
758→
759→		if !strings.HasSuffix(strings.ToLower(path), ".md") {
760→			return nil
761→		}
762→
763→		allowed, checkErr := isPathAllowed(path)
764→		if checkErr != nil || !allowed {
765→			return nil
766→		}
767→
768→		data, err := os.ReadFile(path)
769→		if err != nil {
770→			return nil
771→		}
772→
773→		content := string(data)
774→
775→		// Parse frontmatter tags
776→		if strings.HasPrefix(content, "---\n") {
777→			endIdx := strings.Index(content[4:], "\n---\n")
778→			if endIdx >= 0 {
779→				frontmatter := content[4 : 4+endIdx]
780→				parseFrontmatterTags(frontmatter, tagCounts)
781→			}
782→		}
783→
784→		// Parse inline #tags (skip code blocks)
785→		lines := strings.Split(content, "\n")
786→		inCodeBlock := false
787→		for _, line := range lines {
788→			if strings.HasPrefix(strings.TrimSpace(line), "```") {
789→				inCodeBlock = !inCodeBlock
790→				continue
791→			}
792→			if inCodeBlock {
793→				continue
794→			}
795→			matches := inlineTagRe.FindAllStringSubmatch(line, -1)
796→			for _, match := range matches {
797→				if len(match) >= 2 {
798→					tagCounts[match[1]]++
799→				}
800→			}
801→		}
802→
803→		return nil
804→	})
805→
806→	if err != nil {
807→		return nil, ListTagsOutput{}, fmt.Errorf("failed to list tags: %w", err)
808→	}
809→
810→	// Filter by prefix and sort
811→	var tags []TagCount
812→	for tag, count := range tagCounts {
813→		if input.Prefix == "" || strings.HasPrefix(tag, input.Prefix) {
814→			tags = append(tags, TagCount{Tag: tag, Count: count})
815→		}
816→	}
817→	sort.Slice(tags, func(i, j int) bool {
818→		return tags[i].Tag < tags[j].Tag
819→	})
820→
821→	output := ListTagsOutput{Tags: tags}
822→
823→	textContent := fmt.Sprintf("Found %d unique tags", len(tags))
824→	if len(tags) > 0 {
825→		var lines []string
826→		for _, tc := range tags {
827→			lines = append(lines, fmt.Sprintf("#%s (%d)", tc.Tag, tc.Count))
828→		}
829→		textContent += ":\n" + strings.Join(lines, "\n")
830→	}
831→
832→	result := &mcp.CallToolResult{
833→		Content: []mcp.Content{
834→			&mcp.TextContent{Text: textContent},
835→		},
836→	}
837→	return result, output, nil
838→}
839→
840→// parseFrontmatterTags parses tags from YAML frontmatter content (without delimiters)
841→func parseFrontmatterTags(frontmatter string, tagCounts map[string]int) {
842→	lines := strings.Split(frontmatter, "\n")
843→	inTags := false
844→	for _, line := range lines {
845→		trimmed := strings.TrimSpace(line)
846→
847→		// Check for "tags:" header
848→		if trimmed == "tags:" {
849→			inTags = true
850→			continue
851→		}
852→
853→		// Check for inline tags: tags: [tag1, tag2]
854→		if strings.HasPrefix(trimmed, "tags:") {
855→			rest := strings.TrimSpace(strings.TrimPrefix(trimmed, "tags:"))
856→			if strings.HasPrefix(rest, "[") && strings.HasSuffix(rest, "]") {
857→				inner := rest[1 : len(rest)-1]
858→				for _, tag := range strings.Split(inner, ",") {
859→					tag = strings.TrimSpace(tag)
860→					if tag != "" {
861→						tagCounts[tag]++
862→					}
863→				}
864→			}
865→			inTags = false
866→			continue
867→		}
868→
869→		// Parse block-style tag list items
870→		if inTags {
871→			if strings.HasPrefix(trimmed, "- ") {
872→				tag := strings.TrimSpace(strings.TrimPrefix(trimmed, "- "))
873→				if tag != "" {
874→					tagCounts[tag]++
875→				}
876→			} else if trimmed != "" {
877→				// No longer in tags block
878→				inTags = false
879→			}
880→		}
881→	}
882→}
883→
884→func main() {
885→	// Check command line arguments
886→	if len(os.Args) < 2 {
887→		log.Fatal("Usage: mcp-obsidian <vault-path>")
888→	}
889→
890→	// Get vault path from command line
891→	vaultPath = os.Args[1]
892→
893→	// Expand home directory
894→	if strings.HasPrefix(vaultPath, "~") {
895→		home, err := os.UserHomeDir()
896→		if err != nil {
897→			log.Fatalf("Failed to get home directory: %v", err)
898→		}
899→		vaultPath = filepath.Join(home, vaultPath[1:])
900→	}
901→
902→	// Check if vault path exists
903→	if _, err := os.Stat(vaultPath); os.IsNotExist(err) {
904→		log.Fatalf("Vault path does not exist: %s", vaultPath)
905→	}
906→
907→	// Create MCP server
908→	server := mcp.NewServer(&mcp.Implementation{
909→		Name:    "mcp-obsidian",
910→		Version: "3.0.0",
911→	}, nil)
912→
913→	// Register search_notes tool
914→	mcp.AddTool(server, &mcp.Tool{
915→		Name:        "search_notes",
916→		Description: "Search for notes by filename using case-insensitive matching. Supports regex patterns.",
917→	}, searchNotesHandler)
918→
919→	// Register read_notes tool
920→	mcp.AddTool(server, &mcp.Tool{
921→		Name:        "read_notes",
922→		Description: "Read the content of one or more notes. Returns content with error handling per file.",
923→	}, readNotesHandler)
924→
925→	// Register create_note tool
926→	mcp.AddTool(server, &mcp.Tool{
927→		Name:        "create_note",
928→		Description: "Create a new note with YYYY-MM-DD_slug.md naming convention and YAML frontmatter. Supports tags and subfolder placement.",
929→	}, createNoteHandler)
930→
931→	// Register update_note tool
932→	mcp.AddTool(server, &mcp.Tool{
933→		Name:        "update_note",
934→		Description: "Update an existing note's content. Supports 'replace' (overwrite) and 'append' modes.",
935→	}, updateNoteHandler)
936→
937→	// Register delete_note tool
938→	mcp.AddTool(server, &mcp.Tool{
939→		Name:        "delete_note",
940→		Description: "Delete a markdown note from the vault. Only .md files can be deleted.",
941→	}, deleteNoteHandler)
942→
943→	// Register search_content tool
944→	mcp.AddTool(server, &mcp.Tool{
945→		Name:        "search_content",
946→		Description: "Full-text search across note bodies. Returns matching file paths, line numbers, and snippets. Supports regex patterns.",
947→	}, searchContentHandler)
948→
949→	// Register get_backlinks tool
950→	mcp.AddTool(server, &mcp.Tool{
951→		Name:        "get_backlinks",
952→		Description: "Find all notes that link to a given note via [[wikilinks]]. Supports [[note]] and [[note|alias]] syntax.",
953→	}, getBacklinksHandler)
954→
955→	// Register list_tags tool
956→	mcp.AddTool(server, &mcp.Tool{
957→		Name:        "list_tags",
958→		Description: "List all tags found across the vault from YAML frontmatter and inline #tags. Optionally filter by prefix.",
959→	}, listTagsHandler)
960→
961→	// Log server start to stderr (stdout is used for MCP communication)
962→	fmt.Fprintf(os.Stderr, "MCP Obsidian server starting...\n")
963→	fmt.Fprintf(os.Stderr, "Vault path: %s\n", vaultPath)
964→
965→	// Run the server with stdio transport
966→	if err := server.Run(context.Background(), &mcp.StdioTransport{}); err != nil {
967→		log.Fatalf("Server error: %v", err)
968→	}
969→}
